draw:
var L = 1.0, d = p.d, g = 9.8;
var Ioverm = L * L / 12 + d * d;
var Leq = Ioverm / d;
var T = 2 * Math.PI * Math.sqrt(Leq / g);
var th0 = 0.22;
var th = th0 * Math.cos(2 * Math.PI * t / T);
var F = "12px ui-sans-serif, system-ui, sans-serif";

var px = W * 0.5, py = H * 0.14;
var scale = H * 0.60;                 // pixels per metre of rod
var ux = Math.sin(th), uy = Math.cos(th);   // down the rod
var topX = px - ux * (L / 2 - d) * scale, topY = py - uy * (L / 2 - d) * scale;
var botX = px + ux * (L / 2 + d) * scale, botY = py + uy * (L / 2 + d) * scale;

// support bracket
ctx.fillStyle = C.faint;
ctx.fillRect(px - W * 0.14, py - 26, W * 0.28, 7);
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(px, py - 19); ctx.lineTo(px, py); ctx.stroke();

// vertical reference through the pivot
ctx.setLineDash([3, 5]);
ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(px, py + scale * 0.8); ctx.stroke();
ctx.setLineDash([]);

// the rod
ctx.strokeStyle = C.figure; ctx.lineWidth = 7; ctx.lineCap = "round";
ctx.beginPath(); ctx.moveTo(topX, topY); ctx.lineTo(botX, botY); ctx.stroke();
ctx.lineWidth = 1; ctx.lineCap = "butt";

// pivot
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(px, py, 5, 0, 2 * Math.PI); ctx.fill();

// centre of mass, filled
var cmX = px + ux * d * scale, cmY = py + uy * d * scale;
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(cmX, cmY, 5, 0, 2 * Math.PI); ctx.fill();

// centre of oscillation, hollow
var coX = px + ux * Leq * scale, coY = py + uy * Leq * scale;
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath(); ctx.arc(coX, coY, 6, 0, 2 * Math.PI); ctx.stroke();

// the equivalent simple pendulum, drawn faintly alongside
var sx = px + W * 0.30;
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(sx, py); ctx.lineTo(sx + ux * Leq * scale, py + uy * Leq * scale); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.beginPath(); ctx.arc(sx + ux * Leq * scale, py + uy * Leq * scale, 8, 0, 2 * Math.PI); ctx.fill();
ctx.fillStyle = C.ink; ctx.font = F;
ctx.fillText("equivalent simple pendulum", sx - W * 0.10, py - 34);

ctx.fillStyle = C.accent;
ctx.fillText("centre of mass", cmX + 10, cmY - 4);
ctx.fillText("centre of oscillation", coX + 10, coY + 14);
ctx.fillStyle = C.ink;
ctx.fillText("pivot", px + 10, py - 6);

out.note = "d = " + d.toFixed(3) + " m, equivalent length = " + Leq.toFixed(3) +
  " m, T = " + T.toFixed(3) + " s";
